cat >> tests/vitest/window-child-ownership.test.ts <<'EOF'

describe( 'keep on top', () => {
	let desktop: HTMLElement;
	let manager: WindowManager;

	const paintOrder = (): string[] =>
		[ ...manager.getAll() ]
			.sort(
				( a, b ) =>
					Number( a.element.style.zIndex ) - Number( b.element.style.zIndex ),
			)
			.map( ( w ) => w.id );

	beforeEach( () => {
		installHooksStub();
		_resetWindowControlRegistryForTests();
		registerBuiltInControls();
		desktop = makeDesktop();
		document.body.appendChild( desktop );
		manager = new WindowManager( desktop );
	} );

	afterEach( () => {
		for ( const w of manager.getAll() ) {
			w.destroy();
		}
		desktop.remove();
		_resetWindowControlRegistryForTests();
		clearHooksStub();
	} );

	test( 'stays above windows focused or opened after it, which still take focus', async () => {
		const pinned = await manager.open( cfg( 'pinned' ) );
		const a = await manager.open( cfg( 'a' ) );

		expect( manager.setAlwaysOnTop( 'pinned', true ) ).toBe( true );
		expect( pinned.alwaysOnTop ).toBe( true );
		manager.focus( a );
		const b = await manager.open( cfg( 'b' ) );

		expect( b.isFocused() ).toBe( true );
		expect( paintOrder() ).toEqual( [ 'a', 'b', 'pinned' ] );
	} );

	test( 'pinned windows stack in focus order among themselves; unpinning restores normal stacking', async () => {
		await manager.open( cfg( 'p1' ) );
		await manager.open( cfg( 'p2' ) );
		await manager.open( cfg( 'plain' ) );
		manager.setAlwaysOnTop( 'p1', true );
		manager.setAlwaysOnTop( 'p2', true );

		manager.focus( 'p1' );
		manager.focus( 'plain' );
		expect( paintOrder() ).toEqual( [ 'plain', 'p2', 'p1' ] );

		manager.setAlwaysOnTop( 'p1', false );
		manager.setAlwaysOnTop( 'p2', false );
		expect( paintOrder() ).toEqual( [ 'p2', 'p1', 'plain' ] );
	} );

	test( "a pinned owner's child rides above with it", async () => {
		await manager.open( cfg( 'owner' ) );
		await manager.openChild( 'owner', cfg( 'child' ) );
		manager.setAlwaysOnTop( 'owner', true );
		await manager.open( cfg( 'other' ) );

		expect( paintOrder() ).toEqual( [ 'other', 'owner', 'child' ] );
	} );

	test( 'the title-bar pin toggles it, and the session carries it back', async () => {
		const win = await manager.open( cfg( 'pinned' ) );
		const changed = vi.fn();
		document.addEventListener( 'os-window-always-on-top-changed', changed );
		const pin = win.element.querySelector(
			'.os-window__btn--always-on-top',
		) as HTMLElement;

		pin.dispatchEvent( new CustomEvent( 'os-button-activate' ) );

		document.removeEventListener( 'os-window-always-on-top-changed', changed );
		expect( win.alwaysOnTop ).toBe( true );
		expect( pin.getAttribute( 'aria-pressed' ) ).toBe( 'true' );
		expect( changed ).toHaveBeenCalledTimes( 1 );

		const saved = manager.snapshot().windows[ 0 ];
		expect( saved.alwaysOnTop ).toBe( true );
		win.destroy();
		manager._stack.length = 0;

		const restored = await manager.open( cfg( 'pinned', { alwaysOnTop: saved.alwaysOnTop } ) );
		await manager.open( cfg( 'other' ) );
		expect( restored.alwaysOnTop ).toBe( true );
		expect( paintOrder() ).toEqual( [ 'other', 'pinned' ] );
	} );
} );
EOF
